/**
 * Builds a small folder of Script Commands for capturing store screenshots against, so that a shoot never
 * has to point at a real collection — a personal one leaks employer hostnames, usernames and private links
 * into a public listing, and it cannot be composed to show a feature off.
 *
 * The demo commands are generated by the extension's own generator rather than written out by hand, so they
 * cannot drift from what Create Link Command actually produces.
 *
 * Usage: npm run demo [directory]
 */

import { execFileSync } from "node:child_process";
import { chmod, mkdir, mkdtemp, writeFile } from "node:fs/promises";
import { homedir, tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { pathToFileURL } from "node:url";

const AUTHOR = "Erwann Mest";
const AUTHOR_URL = "https://github.com/kud";

const DRAFTS = [
  // Several commands under one package, to show the list gathering a service together
  { title: "YouTube", target: "https://www.youtube.com", packageName: "YouTube", category: "media" },
  {
    title: "Watch Later",
    target: "https://www.youtube.com/playlist?list=WL",
    packageName: "YouTube",
    category: "media",
  },
  {
    title: "Search Music",
    target: "https://music.youtube.com/search?q={query}",
    packageName: "YouTube",
    category: "music",
  },

  { title: "Gmail", target: "https://mail.google.com", packageName: "Google", category: "admin" },
  { title: "Calendar", target: "https://calendar.google.com", packageName: "Google", category: "admin" },

  // A search, so the Prompts For row and the percent-encoded argument are visible
  {
    title: "Search Articles",
    target: "https://en.wikipedia.org/w/index.php?search={query}",
    packageName: "Wikipedia",
    category: "reference",
  },
  { title: "Search Packages", target: "https://www.npmjs.com/search?q={query}", packageName: "npm", category: "dev" },

  { title: "Netflix", target: "https://www.netflix.com", packageName: "Netflix", category: "media" },
  { title: "Hacker News", target: "https://news.ycombinator.com", packageName: "Hacker News", category: "dev" },
  { title: "Raycast Docs", target: "https://developers.raycast.com", packageName: "Raycast", category: "dev" },

  // A folder and an app-scoped open — the two shapes that are links without being URLs
  { title: "Open Downloads", target: "~/Downloads", packageName: "Finder", category: "system" },
  { title: "Figma", target: "https://www.figma.com", application: "Safari", packageName: "Figma", category: "dev" },

  // A scoped set, so the Work section and the environment filter have something to show.
  // Deliberately generic services — a shoot must never leak an employer's hostnames.
  { title: "Linear", target: "https://linear.app", environment: "work", packageName: "Linear" },
  { title: "Notion", target: "https://www.notion.so", environment: "work", packageName: "Notion" },
];

const directory = resolve(process.argv[2] ?? join(homedir(), "scripts-demo"));

/**
 * The two modules are compiled standalone rather than through the project's build because neither imports
 * anything of its own — a property worth preserving, since losing it turns this into a bundler problem.
 */
const loadGenerator = async () => {
  const outDir = await mkdtemp(join(tmpdir(), "link-commands-demo-"));

  execFileSync(
    "npx",
    [
      "tsc",
      "src/lib/generate-script.ts",
      "src/lib/fetch-icon.ts",
      "--outDir",
      outDir,
      "--module",
      "es2022",
      "--target",
      "es2022",
      "--moduleResolution",
      "bundler",
      "--skipLibCheck",
    ],
    { stdio: "inherit" },
  );

  const generate = await import(pathToFileURL(join(outDir, "generate-script.js")));
  const icon = await import(pathToFileURL(join(outDir, "fetch-icon.js")));

  return { ...generate, ...icon };
};

const writeIcon = async (fetchFavicon, slug, domain) => {
  const buffer = await fetchFavicon(domain);
  if (!buffer) return undefined;

  const assetDirectory = join(directory, "assets", slug);
  await mkdir(assetDirectory, { recursive: true });
  await writeFile(join(assetDirectory, "index.png"), buffer);

  return `./assets/${slug}/index.png`;
};

const main = async () => {
  const { buildScript, domainOf, scriptFilename, fetchFavicon } = await loadGenerator();

  await mkdir(directory, { recursive: true });

  for (const draft of DRAFTS) {
    const domain = domainOf(draft.target);
    // Keyed on the filename stem, matching Create Link Command, so two commands sharing a
    // package cannot overwrite each other's icon.
    const stem = scriptFilename(draft).replace(/\.[^.]+$/, "");
    const iconReference = domain ? await writeIcon(fetchFavicon, stem, domain) : undefined;

    const { filename, contents } = buildScript({ ...draft, author: AUTHOR, authorURL: AUTHOR_URL, iconReference });

    await writeFile(join(directory, filename), contents, "utf8");
    await chmod(join(directory, filename), 0o755);

    console.log(`  ${filename}`);
  }

  console.log(`
${DRAFTS.length} Script Commands written to ${directory}

Next, and this part is manual:

  1. Set this extension's "Script Directories" preference to:
       ${directory}
     Keep a note of what it was — you will want it back.

  2. Restart "npm run dev" so the preference is picked up.

  3. Capture each shot with Raycast's Capture Window command, ticking
     "Save to Metadata" so it lands in metadata/ at 2000x1250:

       1. Search Link Commands, detail pane open on "Search Articles" or
          "Search Packages" — both take an argument, so Target, Package,
          Category and Prompts For are all populated at once
       2. The filter dropdown open, showing Environment / Category / Package
       3. Create Link Command, with a {query} in Target and the Category
          picker open on the discovered list

  4. Restore your own directories in the preference.

  5. Delete this folder when you are done:
       trash ${directory}
`);
};

main().catch((error) => {
  console.error(error);
  process.exit(1);
});
